sys_rte_eb_multiple_input_output_script_.script:
(function(batch, output) {
   for (var i = 0; i < batch.length; i++) {
      var input = batch[i].input; // Value of the input columns concatenated with '|'. 
      // Access input column values by their names, ex: batch[i].column_name
      // In order to access columns containing multiple parts concatenated by a dot, use bracket notation ex. batch[i]['prefix_name.column_name']
      // Add your code here.

      var netmap = JSON.parse(batch[i].u_netmap);
      var id = netmap.id;
      var network_id = netmap.network_id;
      var host = netmap.host;
      var hostip = netmap.hostip;
      var vendor = netmap.vendor;
      var os = netmap.os;
      var status = netmap.status;
      var overallseverity = netmap.overallseverity;
      output[i].u_id = id;
      output[i].u_network_id = network_id;
      output[i].u_host = host;
      output[i].u_hostip = hostip;
      output[i].u_vendor = vendor;
      output[i].u_os = os;
      output[i].u_status = status;
      output[i].u_overallseverity = overallseverity;


      // Set each output element below, accessing output column values by their names
      //output[i].column_name = output_variable_name;
   }
})(batch, output);
